import { randomUUID } from 'node:crypto'
import {
  isOrcaSessionId,
  type OrcaSessionId
} from '../../../../shared/agent-session/identity/orca-session-address'
import type { AgentProviderKey } from '../../identity/agent-provider-key'
import type {
  AgentIdentityClient,
  AgentIdentityLookup
} from '../../identity/agent-identity-worker-client'
import { AgentHookServerAgentIdentities } from '../server-agent-identities'

/** An identity store held in memory: one stable id per key and store path, answered
 *  asynchronously, with no worker thread or file. */
export class MemoryAgentIdentityClient implements AgentIdentityClient {
  private readonly ids = new Map<string, OrcaSessionId>()

  async identify(path: string, key: AgentProviderKey): Promise<AgentIdentityLookup> {
    const keyString = JSON.stringify([path, key])
    const id = this.ids.get(keyString) ?? `${key.agent}_${randomUUID()}`
    if (!isOrcaSessionId(id)) {
      return undefined
    }
    this.ids.set(keyString, id)
    return { id }
  }

  async has(path: string, orcaSessionId: string): Promise<boolean> {
    const pathPrefix = JSON.stringify([path]).slice(0, -1)
    return [...this.ids].some(([key, id]) => id === orcaSessionId && key.startsWith(pathPrefix))
  }

  async providerKeyOf(
    path: string,
    orcaSessionId: string
  ): Promise<{ key: AgentProviderKey | null }> {
    const linked = [...this.ids].find(([keyString, id]) => {
      return id === orcaSessionId && keyString.startsWith(JSON.stringify([path]).slice(0, -1))
    })
    // oxlint-disable-next-line typescript/consistent-type-assertions -- SAFETY: map keys are JSON.stringify([path, key]) written above.
    return { key: linked ? (JSON.parse(linked[0]) as [string, AgentProviderKey])[1] : null }
  }

  async idsOfProviderSession(path: string, providerSessionId: string): Promise<OrcaSessionId[]> {
    const pathPrefix = JSON.stringify([path]).slice(0, -1)
    return [...this.ids]
      .filter(
        ([keyString]) =>
          keyString.startsWith(pathPrefix) &&
          keyString.includes(`"providerSessionId":${JSON.stringify(providerSessionId)}`)
      )
      .map(([, id]) => id)
  }

  readonly isRetiring = false

  retired(): Promise<void> {
    return Promise.resolve()
  }

  dispose(): void {}
}

// Hook-server suites run from source, where the identity worker has no built entry; the worker's
// own suites cover it. Every hook-server owner these suites start gets an in-memory store.
Reflect.set(
  AgentHookServerAgentIdentities.prototype,
  'createAgentIdentityClient',
  () => new MemoryAgentIdentityClient()
)

import { agentSessionRecordFixture } from '../../../native-chat/testing/agent-session-record-test-fixture'
import { agentSessionConversationView } from '../../../../shared/agent-session/lifecycle/leases/agent-session-conversation-view'
import { testOrcaSessionId } from '../../../../shared/agent-session/identity/orca-session-address-test-fixture'
import { formatOrcaSessionAddress as address } from '../../../../shared/agent-session/identity/orca-session-address'
import { fixture } from './crew-read-model.test-fixture'

export const SELF = testOrcaSessionId('aaaaaaaa-1111-4111-8111-aaaaaaaaaaaa')
export const TARGET = testOrcaSessionId('bbbbbbbb-2222-4222-8222-bbbbbbbbbbbb')

export const crewRecord = (sessionId: string) =>
  agentSessionConversationView(agentSessionRecordFixture({ sessionId }))

export function deltaFixture(peers = 0) {
  const f = fixture()
  const records = new Map([[SELF.toString(), crewRecord(SELF)]])
  for (let i = 0; i < peers; i++) {
    const id = testOrcaSessionId(`chat-delta-${i}`)
    records.set(id, crewRecord(id))
    f.db.insertMessage({ from: address(id), to: address(SELF), subject: 'Peer', body: `peer ${i}` })
  }
  const visible = new Set(records.keys())
  f.deps.records = {
    listRecords: () => [...records.values()],
    getRecord: (id) => records.get(id) ?? null,
    getVisibleSessionTabIndex: () => ({ present: true, sessionIds: [...visible] })
  }
  return { ...f, records, visible }
}

export function remembered(f: ReturnType<typeof deltaFixture>, id = TARGET, count = 2) {
  const runs = Array.from({ length: count }, (_, i) =>
    f.db.createRun({
      objective: `history ${i}`,
      coordinatorHandle: null,
      coordinatorPaneKey: null,
      coordinatorOrcaSessionId: id
    })
  )
  f.db.unbindOtherRunsForCoordinator(
    { terminalHandle: null, paneKey: null, orcaSessionId: id },
    f.run.id
  )
  return runs
}

import { vi } from 'vitest'
import type Database from '../../../sqlite/sync-database'
import type { SqliteBindings, SqliteRow } from '../../../sqlite/sqlite-statement'

export function selectedKeyMultiplier(sql: string): number {
  return sql.includes('AS recorded')
    ? 2
    : sql.includes("'handle' AS branch")
      ? 3
      : sql.includes('candidates AS (')
        ? 2
        : sql.includes('coordinator.run_id FROM json_each')
          ? 1
          : 0
}

export type CrewSqlExecution = {
  phase: string
  sql: string
  parameters: SqliteBindings
  method: 'all' | 'get' | 'run' | 'iterate'
  rows: number
  stringChars: number
  results: SqliteRow[]
  chars: number
  bytes: number
  keys: number
  requestChars: number
  failed: boolean
}

export function meterCrewSql(db: Database.Database) {
  const executions: CrewSqlExecution[] = []
  const control: { phase: string; before?: (sql: string) => void } = { phase: 'trigger' }
  const prepare = db.prepare.bind(db)
  const spy = vi.spyOn(db, 'prepare').mockImplementation((sql) => {
    const statement = prepare(sql)
    const begin = (method: CrewSqlExecution['method'], parameters: SqliteBindings) => {
      const multiplier = selectedKeyMultiplier(sql)
      const requested: unknown =
        multiplier && typeof parameters[0] === 'string' ? JSON.parse(parameters[0]) : null
      const entry: CrewSqlExecution = {
        phase: control.phase,
        sql,
        parameters,
        method,
        rows: 0,
        stringChars: 0,
        results: [],
        chars: 0,
        bytes: 0,
        keys: Array.isArray(requested) ? multiplier * requested.length : 0,
        requestChars: multiplier && typeof parameters[0] === 'string' ? parameters[0].length : 0,
        failed: false
      }
      executions.push(entry)
      return entry
    }
    const observe = (entry: CrewSqlExecution, rows: SqliteRow[]) => {
      entry.rows += rows.length
      for (const row of rows) {
        entry.results.push(row)
        for (const value of Object.values(row)) {
          if (typeof value === 'string') {
            entry.stringChars += value.length
          }
        }
      }
      const serialized = JSON.stringify(rows)
      entry.chars += serialized.length
      entry.bytes += Buffer.byteLength(serialized)
    }
    const execute = <T>(entry: CrewSqlExecution, call: () => T): T => {
      try {
        control.before?.(sql)
        return call()
      } catch (error) {
        entry.failed = true
        throw error
      }
    }
    return {
      all: (...parameters) => {
        const entry = begin('all', parameters)
        return execute(entry, () => {
          const rows = statement.all(...parameters)
          observe(entry, rows)
          return rows
        })
      },
      get: (...parameters) => {
        const entry = begin('get', parameters)
        return execute(entry, () => {
          const row = statement.get(...parameters)
          observe(entry, row === undefined ? [] : [row])
          return row
        })
      },
      run: (...parameters) => execute(begin('run', parameters), () => statement.run(...parameters)),
      iterate: (...parameters) => {
        const entry = begin('iterate', parameters)
        const iterator = execute(entry, () => statement.iterate(...parameters))
        return (function* () {
          try {
            for (const row of iterator) {
              observe(entry, [row])
              yield row
            }
          } catch (error) {
            entry.failed = true
            throw error
          }
        })()
      },
      setReadBigInts: (enabled) => statement.setReadBigInts(enabled)
    }
  })
  return { executions, control, restore: () => spy.mockRestore() }
}

export function sqlTotals(executions: CrewSqlExecution[]) {
  return executions.reduce(
    (sum, row) => ({
      all: sum.all + Number(row.method === 'all'),
      get: sum.get + Number(row.method === 'get'),
      run: sum.run + Number(row.method === 'run'),
      iterate: sum.iterate + Number(row.method === 'iterate'),
      rows: sum.rows + row.rows,
      stringChars: sum.stringChars + row.stringChars,
      chars: sum.chars + row.chars,
      bytes: sum.bytes + row.bytes,
      selected: sum.selected + Number(selectedKeyMultiplier(row.sql) > 0),
      keys: sum.keys + row.keys,
      requestChars: sum.requestChars + row.requestChars,
      failed: sum.failed + Number(row.failed)
    }),
    {
      all: 0,
      get: 0,
      run: 0,
      iterate: 0,
      rows: 0,
      stringChars: 0,
      chars: 0,
      bytes: 0,
      selected: 0,
      keys: 0,
      requestChars: 0,
      failed: 0
    }
  )
}

export function crewQueryPlans(db: Database.Database, executions: readonly CrewSqlExecution[]) {
  const actual = executions.filter(
    (row) =>
      !row.failed && row.phase !== 'diagnostic' && (row.method === 'all' || row.method === 'get')
  )
  return {
    version: db.prepare('SELECT sqlite_version() AS version').get(),
    schema: db
      .prepare(
        'SELECT type, name, sql FROM sqlite_master WHERE sql IS NOT NULL ORDER BY type, name'
      )
      .all(),
    plans: actual.map(({ sql, parameters }) => ({
      sql,
      parameters,
      plan: db.prepare(`EXPLAIN QUERY PLAN ${sql}`).all(...parameters)
    }))
  }
}

import type { AgentSessionAccountHome } from '../../../../../shared/agent-session/lifecycle/accounts/agent-session-account-home'
import { readTestJournalSnapshot } from '../../../agent-session-journal/journal-observation.test-support'
import type { AgentMessageSource } from '../../../../../shared/agent-session/journal/agent-session-message-source'
import { vi, type Mock } from 'vitest'
import { parseAgentJournalItemKey } from '../../../../../shared/agent-session/journal/agent-session-journal-item-key'
import { AGENT_JOURNAL_THREAD_SCOPE } from '../../../../../shared/agent-session/journal/agent-session-journal-types'
import { activeProviderContext } from '../../../../../shared/agent-session/conversation-context/agent-session-provider-context'
import {
  claudeProviderHandle,
  codexProviderHandle
} from '../../../../../shared/agent-session/lifecycle/provider-handles/agent-session-provider-handle-encoding'
import type { AgentSessionRecordStore } from '../../../../runtime/agent-session/records/agent-session-record-store'
import type { StructuredAgentSessionAdapter } from '../../providers/structured-agent-session-adapter'
import type { StructuredAgentSessionEventSink } from '../../journal-ingress/structured-agent-session-event-sink'
import type { StructuredAgentSessionHost } from '../structured-agent-session-host'
import { startsWhenPublished } from './structured-agent-session-instant-start.test-fixture'
import {
  HOST_TEST_NOW as NOW,
  HOST_TEST_THREAD as THREAD
} from './structured-agent-session-host-test-data.test-fixture'

export type QueuedRigProviderOptions = {
  acquiredAccountHome?: () => AgentSessionAccountHome
  agent?: 'claude'
  rewind?: NonNullable<StructuredAgentSessionAdapter['rewind']>
  recoverRewind?: NonNullable<StructuredAgentSessionAdapter['recoverRewind']>
  /** Resume the saved thread on later children after close/death. */
  restartable?: true
  /** Startup never answers; queued input cannot run. */
  starting?: true
  /** Wait for stopped work to end or grace expiry before closing the child. */
  windsDown?: true
  /** The model its child reports running; otherwise the agent's own `default`. */
  reportsModel?: string
  reportsEffort?: string
}

/** How long a winding-down child is given after the interrupt before the Stop ends it. */
export const QUEUED_RIG_STOP_GRACE_MS = 2_000

export function createQueuedRigProvider(
  store: Pick<AgentSessionRecordStore, 'getRecord'>,
  options: QueuedRigProviderOptions,
  host: () => StructuredAgentSessionHost
) {
  // Admitted sends owe work until explicitly settled.
  const dispatch: Mock<StructuredAgentSessionAdapter['dispatch']> = vi.fn(async () => ({
    state: 'admitted' as const
  }))
  const starts: Mock<() => void> = vi.fn()
  let startHold: Promise<void> | null = null
  let startFailure: Error | null = null
  // Acceptance precedes the later finishCompact turn-end event.
  const compact: Mock<NonNullable<StructuredAgentSessionAdapter['compact']>> = vi.fn(async () => ({
    state: 'accepted' as const,
    providerIdentity: null
  }))
  const cancelTurn: Mock<StructuredAgentSessionAdapter['cancelTurn']> = vi.fn(async () => ({
    cancelled: true
  }))
  const setOption: Mock<StructuredAgentSessionAdapter['setOption']> = vi.fn(async () => undefined)
  const closeSession: Mock<NonNullable<StructuredAgentSessionAdapter['closeSession']>> = vi.fn(
    async () => true
  )
  let events: StructuredAgentSessionEventSink | undefined
  let proveOpen: (() => void) | null = null

  const reported = () => ({
    model: options.reportsModel ?? 'default',
    ...(options.reportsEffort ? { effort: options.reportsEffort } : {})
  })
  const scripted: StructuredAgentSessionAdapter = {
    open: () =>
      options.starting
        ? new Promise((resolve) => {
            proveOpen = () => resolve({ reportedOptions: reported() })
          })
        : Promise.resolve({ reportedOptions: reported() }),
    acquire: async ({ identity, fence, spawnToken, events: sink }) => {
      starts()
      const hold = startHold
      startHold = null
      await hold
      const failure = startFailure
      startFailure = null
      if (failure) {
        throw failure
      }
      events = sink
      const record = store.getRecord(identity.sessionId)
      const context = record ? activeProviderContext(record) : null
      const resumes = options.restartable === true && context?.head != null
      const thread = context?.pendingClear
        ? `${THREAD}-context-${record!.providerContextBoundary!.operationId}`
        : (context?.head?.handle.nativeId ?? THREAD)
      const accountHome = options.acquiredAccountHome?.()
      return {
        process: {
          hostId: 'local',
          pid: 4242,
          processStartTimeMs: 1_700_000_000_000,
          spawnToken
        },
        acquisitionGeneration: 'generation-1',
        ...(accountHome ? { accountHome } : {}),
        link: {
          linkId: `link-${fence}`,
          handle:
            identity.agent === 'claude'
              ? claudeProviderHandle(thread, null)
              : codexProviderHandle(thread),
          origin: resumes ? ('resumed' as const) : ('created' as const),
          mintedAtFence: fence,
          observedAt: NOW
        }
      }
    },
    dispatch,
    captureMessageSteeringInputs: () => ({
      kind: 'codex',
      compiler: {
        active: reported(),
        activeInput: reported(),
        defaults: reported(),
        models: [],
        listedServiceTiers: []
      }
    }),
    closeSession,
    releaseAcquisition: vi.fn(async () => true),
    compact,
    cancelTurn,
    answerPrompt: vi.fn(async ({ commit }) => commit()),
    setOption,
    ...(options.rewind
      ? {
          rewind: options.rewind,
          rewindSupport: () => ({ supported: true as const }),
          prepareRewind: async ({ sessionId, beforeTurnId }) => {
            const record = store.getRecord(sessionId)!
            const threadId = activeProviderContext(record).head!.handle.nativeId
            const turns = (
              await readTestJournalSnapshot(
                host().collaboratorsForTests().sessions.get(sessionId)!.journal
              )
            ).submissions.flatMap(({ providerItemId }) => {
              const identity = providerItemId ? parseAgentJournalItemKey(providerItemId) : null
              return identity?.provider === 'codex' && identity.threadId === threadId
                ? [identity.turnId]
                : []
            })
            const index = turns.indexOf(beforeTurnId)
            return index === -1
              ? { ok: false as const, reason: 'invalid-target' as const }
              : {
                  ok: true as const,
                  revert: { threadId, beforeTurnId, keptTurnId: turns[index - 1] ?? null }
                }
          }
        }
      : {}),
    ...(options.recoverRewind ? { recoverRewind: options.recoverRewind } : {}),
    ...(options.windsDown
      ? {
          awaitStoppedRequestEnd: async (sessionId: string, stoppedAt: number) => {
            while (
              Date.now() < stoppedAt + QUEUED_RIG_STOP_GRACE_MS &&
              (await working(sessionId))
            ) {
              await new Promise((resolve) => setTimeout(resolve, 5))
            }
          }
        }
      : {})
  }

  async function working(sessionId: string): Promise<boolean> {
    return (await host().currentWork(sessionId))?.working() ?? false
  }

  const adapter = options.starting ? scripted : startsWhenPublished(scripted, host)

  function finishCompact(): void {
    const { command } = compact.mock.calls.at(-1)![0]
    events!.appendLifecycleBatch!(
      `turn-completed:${command.clientMessageId}`,
      [
        {
          kind: 'item',
          identity: command.identity,
          body: { ...command.running, state: 'completed', outcome: 'success', completedAt: NOW },
          turnScope: AGENT_JOURNAL_THREAD_SCOPE
        }
      ],
      { lifecycle: true }
    )
  }

  function holdNextStart(): () => void {
    let release = (): void => {}
    startHold = new Promise<void>((resolve) => (release = resolve))
    return () => release()
  }

  function failNextStart(error: Error): void {
    startFailure = error
  }

  function providerEvents(): StructuredAgentSessionEventSink {
    if (!events) {
      throw new Error('no provider bound')
    }
    return events
  }

  return {
    adapter,
    proveOpen: () => proveOpen?.(),
    dispatch,
    starts,
    holdNextStart,
    failNextStart,
    compact,
    cancelTurn,
    setOption,
    closeSession,
    finishCompact,
    providerEvents
  }
}

export function eventually(assertion: () => void | Promise<void>): Promise<void> {
  return vi.waitFor(assertion, { timeout: 10_000 })
}

export type RigSendOptions = {
  internal?: true
  from?: AgentMessageSource
  carried?: Readonly<Record<string, string>>
}

import { mkdtempSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import Database from '../../../../sqlite/sync-database'
import { afterEach, describe, expect, it } from 'vitest'
import { OrchestrationDb } from '../orchestration-db'
import { createRootDispatch } from '../root-dispatch-test-fixture'

const runId = 'run_legacy_local'
const NEW_INDEXES = [
  'idx_dispatch_contexts_origin',
  'idx_dispatch_creator_orca_session_id',
  'idx_dispatch_creator_pane_key',
  'idx_bot_requests_send',
  'idx_bot_requests_awaiting',
  'idx_question_threads_awaiting',
  'idx_remote_owned_questions_awaiting',
  'idx_dispatch_contexts_for_message',
  'idx_peer_questions_out_awaiting'
]
const TAKE_COLUMNS = [
  ['bot_requests', 'taken_by'],
  ['bot_requests', 'awaiting'],
  ['question_threads', 'taken_by'],
  ['question_threads', 'awaiting'],
  ['question_threads', 'told'],
  ['remote_owned_questions', 'taken_by'],
  ['remote_owned_questions', 'awaiting'],
  ['remote_owned_questions', 'ended'],
  ['dispatch_contexts', 'for_message_id']
] as const
const BOT_TABLES = [
  'bot_requests',
  'bot_request_outcomes',
  'bot_conversation_acts_for',
  'bot_run_resends'
]

describe('v47-v48 bot dispatch migrations', () => {
  // Use and clean a real temp directory: TMPDIR is absent on Windows CI.
  const tempRoots: string[] = []

  afterEach(() => {
    for (const root of tempRoots.splice(0)) {
      rmSync(root, { recursive: true, force: true })
    }
  })

  function dbPath(): string {
    const root = mkdtempSync(join(tmpdir(), 'orca-bot-dispatch-migration-'))
    tempRoots.push(root)
    return join(root, 'orchestration.db')
  }

  function seedWithDispatch(path: string): string {
    const db = new OrchestrationDb(path)
    const task = db.createTask({ runId, spec: 'seeded' })
    createRootDispatch(db, task.id, 'term_seeded')
    db.close()
    return task.id
  }

  function hasIndex(db: OrchestrationDb, name: string): boolean {
    return !!db.db
      .prepare("SELECT 1 FROM sqlite_master WHERE type = 'index' AND name = ?")
      .get(name)
  }

  function expectCurrentSchema(path: string, seededTaskId?: string): void {
    const db = new OrchestrationDb(path)
    try {
      expect(db.db.pragma('user_version', { simple: true })).toBe(50)
      expect(TAKE_COLUMNS.filter(([table, column]) => !db.hasColumn(table, column))).toEqual([])
      expect(db.hasColumn('dispatch_contexts', 'creator_turn_source')).toBe(true)
      expect(db.hasColumn('dispatch_contexts', 'origin_ref')).toBe(true)
      expect(db.hasColumn('bot_requests', 'send_key')).toBe(true)
      expect(NEW_INDEXES.filter((name) => !hasIndex(db, name))).toEqual([])
      if (seededTaskId) {
        expect(db.getDispatchContext(seededTaskId)?.assignee_handle).toBe('term_seeded')
      }
      const task = db.createTask({ runId, spec: 'after open' })
      const dispatch = createRootDispatch(db, task.id, `term_${task.id}`)
      expect(dispatch.creator_turn_source).toBeNull()
      expect(dispatch.origin_ref).toBeNull()
    } finally {
      db.close()
    }
  }

  /** Strip what v47 and v48 add, as a database last opened by a build at v46 has it. */
  function rewindToV46(path: string): void {
    const raw = new Database(path)
    for (const index of NEW_INDEXES) {
      raw.exec(`DROP INDEX IF EXISTS ${index}`)
    }
    raw.exec('ALTER TABLE dispatch_contexts DROP COLUMN origin_ref')
    raw.exec('ALTER TABLE dispatch_contexts DROP COLUMN creator_turn_source')
    for (const table of BOT_TABLES) {
      raw.exec(`DROP TABLE ${table}`)
    }
    raw.pragma('user_version = 46')
    raw.close()
  }

  it('adds who took each question to a v49 database and keeps its rows', () => {
    const path = dbPath()
    const taskId = seedWithDispatch(path)
    const raw = new Database(path)
    for (const index of NEW_INDEXES.slice(4)) {
      raw.exec(`DROP INDEX IF EXISTS ${index}`)
    }
    for (const [table, column] of TAKE_COLUMNS) {
      raw.exec(`ALTER TABLE ${table} DROP COLUMN ${column}`)
    }
    raw.exec('DROP TABLE peer_questions_out')
    raw.pragma('user_version = 49')
    raw.close()

    expectCurrentSchema(path, taskId)
  })

  it('opens a fresh database at v48, and again unchanged', () => {
    const path = dbPath()
    expectCurrentSchema(path)
    expectCurrentSchema(path)
  })

  it('migrates a v46 database without the bot columns and keeps its rows', () => {
    const path = dbPath()
    const taskId = seedWithDispatch(path)
    rewindToV46(path)

    expectCurrentSchema(path, taskId)
  })

  it('migrates a v46 database that already has the bot columns, indexes and an early bot mail table', () => {
    const path = dbPath()
    const taskId = seedWithDispatch(path)
    const raw = new Database(path)
    // Early bot builds: no 'status' purpose, no send key, one handoff per bot per request.
    raw.exec(`
      DROP INDEX idx_bot_requests_send;
      DROP TABLE bot_requests;
      CREATE TABLE bot_requests (
        message_id  TEXT PRIMARY KEY,
        root_key    TEXT NOT NULL,
        from_bot_id TEXT,
        to_bot_id   TEXT NOT NULL,
        purpose     TEXT NOT NULL CHECK(purpose IN ('handoff', 'question')),
        depth       INTEGER NOT NULL,
        record      TEXT NOT NULL,
        created_at  TEXT NOT NULL DEFAULT (datetime('now'))
      );
      CREATE UNIQUE INDEX idx_bot_requests_one_handoff ON bot_requests(root_key, to_bot_id)
        WHERE purpose = 'handoff';
      CREATE TABLE bot_request_roots (root_key TEXT PRIMARY KEY);
      INSERT INTO bot_requests (message_id, root_key, to_bot_id, purpose, depth, record)
        VALUES ('msg_early', 'root_early', 'bot_b', 'handoff', 1, '{}');
    `)
    raw.pragma('user_version = 46')
    raw.close()

    expectCurrentSchema(path, taskId)
    const db = new OrchestrationDb(path)
    try {
      expect(db.db.prepare('SELECT message_id, send_key FROM bot_requests').all()).toEqual([
        { message_id: 'msg_early', send_key: null }
      ])
      db.db.exec(`INSERT INTO bot_requests (message_id, root_key, to_bot_id, purpose, depth, record)
        VALUES ('msg_status', 'root_early', 'bot_b', 'status', 1, '{}')`)
      expect(hasIndex(db, 'idx_bot_requests_one_handoff')).toBe(false)
      expect(
        db.db.prepare("SELECT 1 FROM sqlite_master WHERE name = 'bot_request_roots'").get()
      ).toBeUndefined()
    } finally {
      db.close()
    }
  })

  it('keeps the bot columns, mail rows and indexes of a v46 database an earlier bots build already shaped', () => {
    const path = dbPath()
