  server.ingestProgramStatusFacet({ paneKey: PANE, facet: facet ?? null })
  const event = {
    paneKey: PANE,
    tabId: 'tab-1',
    worktreeId: 'wt-1',
    connectionId: null,
    fromProgramStatus: true as const,
    payload: payloads[0]!.payload
  }
  server.ingestTerminalStatus(event)
  return event
}

