final class AuthenticatedConnectionHangupMonitorTests: XCTestCase {






    func testStartReportsHangupQueuedAfterSuccessfulSetup() throws {
        let descriptors = try makeSocketPair()
        let hangup = expectation(description: "queued peer hangup")
        let monitor = try AuthenticatedConnectionHangupMonitor(
            fileDescriptor: descriptors.local,
            onHangup: {
                hangup.fulfill()
            }
        )

        close(descriptors.peer)
        monitor.start()

        wait(for: [hangup], timeout: 1)
        monitor.cancel()
        close(descriptors.local)
    }
}



private func makeSocketPair() throws -> (local: Int32, peer: Int32) {
    var descriptors: [Int32] = [0, 0]
    guard socketpair(AF_UNIX, SOCK_STREAM, 0, &descriptors) == 0 else {
        throw POSIXError(.EIO)
    }
    return (descriptors[0], descriptors[1])
}

import { existsSync, lstatSync, readFileSync, writeFileSync } from 'node:fs'
import type { GrantAccessOptions, WindowsAce, WindowsDacl } from '@orca/windows-security'
import type { WindowsSecurityAddon } from './windows-security-addon'

export const FAKE_USER_SID = 'S-1-5-21-1-2-3-1001'

/** What an untouched path reads back as: inherited from a relocated root like `C:\orca-data`. */
export const INHERITED_SDDL = `D:AI(A;ID;FA;;;SY)(A;ID;FA;;;BA)(A;ID;FA;;;${FAKE_USER_SID})(A;ID;0x1301bf;;;AU)`

const SID_ALIASES: Record<string, string> = {
  AC: 'S-1-15-2-1',
  AU: 'S-1-5-11',
  BA: 'S-1-5-32-544',
  BU: 'S-1-5-32-545',
  SY: 'S-1-5-18',
  WD: 'S-1-1-0'
}
const ACE_TYPES: Record<string, number> = { A: 0, D: 1, OA: 5, XA: 9 }
const ACE_FLAGS: Record<string, number> = { OI: 0x1, CI: 0x2, NP: 0x4, IO: 0x8, ID: 0x10 }
const RIGHTS: Record<string, number> = { FA: 0x1f01ff, FR: 0x120089, GA: 0x10000000 }

/** Test-only SDDL parser for native getDaclAces-shaped fixtures; production never parses SDDL. */
export function daclFromSddl(sddl: string): WindowsDacl | null {
  if (sddl.includes('NO_ACCESS_CONTROL')) {
    return null
  }
  const match = /^D:([A-Z]*)(.*)$/.exec(sddl)
  if (!match) {
    throw new Error(`fixture SDDL is not a DACL: ${sddl}`)
  }
  const aces: WindowsAce[] = []
  // A conditional ACE's trailing expression holds parentheses; only its type matters here.
  for (const [, body] of match[2]!.matchAll(/\(((?:[^()]|\([^()]*\))*)\)/g)) {
    const [type = '', flags = '', rights = '', , , sid = ''] = body!.split(';')
    const plain = type === 'A' || type === 'D'
    aces.push({
      type: ACE_TYPES[type] ?? 0xff,
      flags: (flags.match(/../g) ?? []).reduce((all, token) => all | (ACE_FLAGS[token] ?? 0), 0),
      mask: RIGHTS[rights] ?? (Number.parseInt(rights, 16) || 0),
      sid: plain ? (SID_ALIASES[sid] ?? sid) : null
    })
  }
  return { protected: match[1]!.includes('P'), aces }
}

export type FakeWindowsSecurityCall =
  | { op: 'get' | 'set' | 'setAsync'; path: string; addonPath: string; sddl?: string }
  | { op: 'create'; path: string; addonPath: string; sddl: string }
  | {
      op: 'grant' | 'grantAsync'
      path: string
      addonPath: string
      sid: string
      mask: number
      options: GrantAccessOptions
    }

export type FakeWindowsSecurity = WindowsSecurityAddon & {
  calls: FakeWindowsSecurityCall[]
  /** The SDDL each path reads back as; absent paths read as INHERITED_SDDL. */
  dacls: Map<string, string>
  /** Paths whose writes (set, create, grant) throw. */
  failing: Set<string>
  /** When set, setDaclSddlAsync parks here instead of settling. */
  holdAsync: boolean
  /** Settles every parked setDaclSddlAsync. */
  releaseAsync: () => void
  callsFor: (op: FakeWindowsSecurityCall['op'], path?: string) => FakeWindowsSecurityCall[]
}

function win32Error(syscall: string): Error {
  return new Error(`${syscall} failed with Win32 error 5`)
}

/** The path the test used: the addon wrapper namespaces (`\\?\`) every path on Windows. */
function plainPath(addonPath: string): string {
  if (addonPath.startsWith('\\\\?\\UNC\\')) {
    return `\\\\${addonPath.slice(8)}`
  }
  return addonPath.startsWith('\\\\?\\') ? addonPath.slice(4) : addonPath
}

/** An in-memory stand-in for native/windows-security; files it creates are real. */
export function createFakeWindowsSecurity(): FakeWindowsSecurity {
  const parked: (() => void)[] = []
  const credentials = new Map<string, Buffer>()
  const record = <T extends FakeWindowsSecurityCall['op']>(
    op: T,
    addonPath: string,
    rest: Record<string, unknown> = {}
  ): string => {
    const path = plainPath(addonPath)
    // oxlint-disable-next-line typescript/consistent-type-assertions -- SAFETY: each caller passes exactly the fields its op's union member declares.
    fake.calls.push({ op, path, addonPath, ...rest } as FakeWindowsSecurityCall)
    return path
  }
  const fake: FakeWindowsSecurity = {
    calls: [],
    dacls: new Map(),
    failing: new Set(),
    holdAsync: false,
    releaseAsync: () => parked.splice(0).forEach((settle) => settle()),
    callsFor: (op, path) =>
      fake.calls.filter((call) => call.op === op && (path === undefined || call.path === path)),
    currentUserSid: () => FAKE_USER_SID,
    readGenericCredential: (target) => credentials.get(target) ?? null,
    writeGenericCredential: (target, _user, bytes) => {
      credentials.set(target, Buffer.from(bytes))
    },
    readFileWithDacl: (addonPath, maxBytes) => {
      if (!existsSync(addonPath)) {
        return null
      }
      const stat = lstatSync(addonPath)
      if (!stat.isFile() || stat.size > maxBytes) {
        throw win32Error('ReadFile')
      }
      return {
        data: readFileSync(addonPath),
        dacl: daclFromSddl(fake.dacls.get(plainPath(addonPath)) ?? INHERITED_SDDL)
      }
    },
    clearStdHandleInheritance: () => [],
    spawnDetachedIsolated: () => {
      throw new Error('spawnDetachedIsolated is not faked')
    },
    isolatedSpawnBreaksAwayFromJob: () => true,
    hasNativeExport: () => true,
    getDaclAces: (addonPath) => {
      const path = record('get', addonPath)
      return daclFromSddl(fake.dacls.get(path) ?? INHERITED_SDDL)
    },
    setDaclSddl: (addonPath, sddl) => {
      const path = record('set', addonPath, { sddl })
      if (fake.failing.has(path)) {
        throw win32Error('SetNamedSecurityInfoW')
      }
      fake.dacls.set(path, sddl)
    },
    setDaclSddlAsync: (addonPath, sddl) => {
      const path = record('setAsync', addonPath, { sddl })
      const settle = (resolve: () => void, reject: (error: Error) => void): void => {
        if (fake.failing.has(path)) {
          reject(win32Error('SetNamedSecurityInfoW'))
          return
        }
        fake.dacls.set(path, sddl)
        resolve()
      }
      return new Promise((resolve, reject) => {
        if (fake.holdAsync) {
          parked.push(() => settle(resolve, reject))
          return
        }
        settle(resolve, reject)
      })
    },
    createFileWithDacl: (addonPath, sddl, data) => {
      const path = record('create', addonPath, { sddl })
      if (fake.failing.has(path)) {
        throw win32Error('CreateFileW')
      }
      writeFileSync(addonPath, data, { flag: 'wx' })
      fake.dacls.set(path, sddl)
    },
    grantAccess: (addonPath, sid, mask, options) => {
      const path = record('grant', addonPath, { sid, mask, options })
      if (fake.failing.has(path)) {
        throw win32Error('SetNamedSecurityInfoW')
      }
    },
    grantAccessAsync: (addonPath, sid, mask, options) => {
      const path = record('grantAsync', addonPath, { sid, mask, options })
      return fake.failing.has(path)
        ? Promise.reject(win32Error('SetNamedSecurityInfoW'))
        : Promise.resolve()
    }
  }
  return fake
}

import { readFileSync } from 'node:fs'
import process from 'node:process'
import type { Store } from '../../../src/main/persistence/loading-store/store'
import { OrcaRuntimeService } from '../../../src/main/runtime/orca-runtime'
import { RpcDispatcher } from '../../../src/main/runtime/rpc/dispatcher'
import { SESSION_TAB_METHODS } from '../../../src/main/runtime/rpc/methods/session-tabs/session-tabs'
import { SESSION_TAB_CLOSE_INTENT_RUNTIME_CAPABILITY } from '../../../src/shared/remote-runtime/protocol/session-tabs-runtime-capabilities'
import type { RuntimeMobileSessionTabsSnapshot } from '../../../src/shared/remote-runtime/session-graph/runtime-session-contracts'
import { createDesktopDiscoveredDaemonRouter } from './daemon-generation-desktop-discovery'
import { createDaemonGenerationProfileStore } from './daemon-generation-profile-store'

type FixtureSession = {
  protocolVersion: number
  sessionId: string
  rootPid: number
  worktreeId: string
  tabId: string
  closeContract: 'capable' | 'legacy'
}

type FixtureConfig = {
  generations: { protocolVersion: number; socketPath: string; tokenPath: string }[]
  currentProtocolVersion: number
  daemonDir: string
  historyDir: string
  cwd: string
  sessions: FixtureSession[]
}

async function waitFor(description: string, predicate: () => boolean): Promise<void> {
  const deadline = Date.now() + 10_000
  while (Date.now() <= deadline) {
    if (predicate()) {
      return
    }
    await new Promise<void>((resolve) => setTimeout(resolve, 25))
  }
  throw new Error(`Timed out waiting for ${description}`)
}

const LEGACY_VIEWER = {
  clientKind: 'runtime' as const,
  clientId: 'legacy-viewer',
  pairedDeviceId: 'legacy-viewer',
  connectionId: 'legacy-viewer-generation-1',
  callSite: 'legacy-viewer:stale-pty-exit-cleanup',
  wireReason: null
}
const CAPABLE_VIEWER = {
  clientKind: 'runtime' as const,
  clientId: 'capable-viewer',
  pairedDeviceId: 'capable-viewer',
  connectionId: 'capable-viewer-generation-2',
  clientCapabilities: [SESSION_TAB_CLOSE_INTENT_RUNTIME_CAPABILITY],
  callSite: 'capable-viewer:stale-pty-exit-cleanup',
  wireReason: null
}
const OBSERVER = {
  clientKind: 'runtime' as const,
  clientId: 'current-viewer',
  pairedDeviceId: 'current-viewer',
  connectionId: 'observer-generation-3'
}

function readConfig(): FixtureConfig {
  const configIndex = process.argv.indexOf('--config')
  const configPath = configIndex !== -1 ? process.argv[configIndex + 1] : undefined
  if (!configPath) {
    throw new Error('Legacy close client requires --config <path>')
  }
  return JSON.parse(readFileSync(configPath, 'utf8')) as FixtureConfig
}

async function dispatchReasonlessClose(
  dispatcher: RpcDispatcher,
  session: FixtureSession,
  sequence: number,
  viewer: typeof LEGACY_VIEWER | typeof CAPABLE_VIEWER
): Promise<Record<string, unknown>> {
  const requestId = `${session.closeContract}-close-${sequence}`
  return await new Promise((resolve, reject) => {
    void dispatcher
      .dispatchStreaming(
        {
          id: requestId,
          authToken: '[REDACTED]',
          method: 'session.tabs.close',
          params: { worktree: `id:${session.worktreeId}`, tabId: session.tabId }
        },
        (serialized) => resolve(JSON.parse(serialized) as Record<string, unknown>),
        viewer
      )
      .catch(reject)
  })
}

async function dispatchObserverList(
  dispatcher: RpcDispatcher,
  session: FixtureSession,
  sequence: number
): Promise<Record<string, unknown>> {
  return await new Promise((resolve, reject) => {
    void dispatcher
      .dispatchStreaming(
        {
          id: `observer-list-${sequence}`,
          authToken: '[REDACTED]',
          method: 'session.tabs.list',
          params: { worktree: `id:${session.worktreeId}` }
        },
        (serialized) => resolve(JSON.parse(serialized) as Record<string, unknown>),
        OBSERVER
      )
      .catch(reject)
  })
}

async function waitForFinish(): Promise<void> {
  await new Promise<void>((resolve) => {
    process.on('message', (message) => {
      if ((message as { type?: unknown })?.type === 'finish') {
        resolve()
      }
    })
  })
}

async function main(): Promise<void> {
  const config = readConfig()
  const { router } = await createDesktopDiscoveredDaemonRouter(config)
  let store: Store | null = null
  try {
    const outputBySessionId = new Map<string, string>()
    router.onData((event) => {
      outputBySessionId.set(
        event.id,
        `${outputBySessionId.get(event.id) ?? ''}${event.data}`.slice(-32_768)
      )
    })
    await router.getCurrentAdapter().listProcesses()
    await router.discoverLegacySessions()
    for (const session of config.sessions) {
      const attached = await router.spawn({
        sessionId: session.sessionId,
        isNewSession: false,
        cols: 100,
        rows: 30,
        cwd: config.cwd
      })
      if (!attached.isReattach || attached.pid !== session.rootPid) {
        throw new Error(`Legacy close fixture changed ${session.sessionId} incarnation`)
      }
    }

    store = createDaemonGenerationProfileStore(config.cwd)
    const runtime = new OrcaRuntimeService(store)
    const calls: Record<string, unknown>[] = []
    const sessionByTabId = new Map(config.sessions.map((session) => [session.tabId, session]))
    runtime.setPtyController({
      write: (ptyId, data) => {
        router.write(ptyId, data)
        return true
      },
      kill: () => false,
      listProcesses: (_hostId, options) => router.listProcesses(options),
      hasPty: (ptyId) => router.hasPty(ptyId),
      getForegroundProcess: (ptyId) => router.getForegroundProcess(ptyId)
    })
    runtime.setNotifier({
      closeTerminal: () => {
        throw new Error('Legacy close fixture unexpectedly used the pane-close fallback')
      },
      closeTerminalTab: async (tabId: string) => {
        const session = sessionByTabId.get(tabId)
        if (!session) {
          throw new Error(`Legacy close fixture received unknown tab ${tabId}`)
        }
        calls.push({
          callSite: 'RuntimeNotifier.closeTerminalTab -> DaemonPtyRouter.shutdown',
          immediate: true,
          tabId,
          worktreeId: session.worktreeId,
          sessionId: session.sessionId
        })
        await router.shutdown(session.sessionId, { immediate: true })
      }
    } as never)
    runtime.attachWindow(1)

    const viewers = config.sessions.map((session, index) => {
      const leafId = `00000000-0000-4000-8000-${String(index + 1).padStart(12, '0')}`
      const tab = {
        type: 'terminal' as const,
        id: `${session.tabId}::${leafId}`,
        parentTabId: session.tabId,
        leafId,
        ptyId: session.sessionId,
        title: session.tabId,
        isActive: true
      }
      const snapshot: RuntimeMobileSessionTabsSnapshot = {
        worktree: session.worktreeId,
        publicationEpoch: `legacy-viewer-${index + 1}`,
        snapshotVersion: 1,
        activeGroupId: null,
        activeTabId: tab.id,
        activeTabType: 'terminal',
        tabs: [tab]
      }
      return { session, tab, snapshot }
    })
    runtime.syncWindowGraph(1, {
      tabs: viewers.map(({ session, tab }) => ({
        tabId: tab.parentTabId,
        worktreeId: session.worktreeId,
        title: tab.title,
        activeLeafId: tab.leafId,
        layout: null
      })),
      leaves: viewers.map(({ session, tab }, index) => ({
        tabId: tab.parentTabId,
        worktreeId: session.worktreeId,
        leafId: tab.leafId,
        paneRuntimeId: index + 1,
        ptyId: session.sessionId,
        paneTitle: tab.title
      })),
      mobileSessionTabs: viewers.map(({ snapshot }) => snapshot)
    })

    const dispatcher = new RpcDispatcher({ runtime, methods: SESSION_TAB_METHODS })
    const observerBefore: Record<string, unknown>[] = []
    for (const [index, session] of config.sessions.entries()) {
      observerBefore.push(await dispatchObserverList(dispatcher, session, index + 1))
    }
    const capableResponses: Record<string, unknown>[] = []
    for (const [index, session] of config.sessions
      .filter((candidate) => candidate.closeContract === 'capable')
      .entries()) {
      capableResponses.push(
        await dispatchReasonlessClose(dispatcher, session, index + 1, CAPABLE_VIEWER)
      )
    }
    const observerAfterCapable: Record<string, unknown>[] = []
    for (const [index, session] of config.sessions.entries()) {
      observerAfterCapable.push(await dispatchObserverList(dispatcher, session, index + 101))
    }
    const legacyResponses: Record<string, unknown>[] = []
    for (const [index, session] of config.sessions
      .filter((candidate) => candidate.closeContract === 'legacy')
      .entries()) {
      legacyResponses.push(
        await dispatchReasonlessClose(dispatcher, session, index + 1, LEGACY_VIEWER)
      )
    }
    const observerAfter: Record<string, unknown>[] = []
    for (const [index, session] of config.sessions.entries()) {
      observerAfter.push(await dispatchObserverList(dispatcher, session, index + 201))
    }
    const postClosePing: Record<string, boolean> = {}
    for (const [index, session] of config.sessions.entries()) {
      if (calls.some((call) => call.sessionId === session.sessionId)) {
        postClosePing[session.sessionId] = false
        continue
      }
      const nonce = `post-close-${index + 1}`
      try {
        router.write(
          session.sessionId,
          `PING legacy-close-v${session.protocolVersion}-live ${nonce}\r`
        )
        await waitFor(`${session.sessionId} post-close reply`, () =>
          (outputBySessionId.get(session.sessionId) ?? '').includes(
            `ORCA_GENERATION_CANARY_ACK legacy-close-v${session.protocolVersion}-live ${nonce}`
          )
        )
        postClosePing[session.sessionId] = true
      } catch {
        postClosePing[session.sessionId] = false
      }
    }
    process.send?.({
      type: 'legacy-close-complete',
      capableInitiator: CAPABLE_VIEWER,
      legacyInitiator: LEGACY_VIEWER,
      observer: {
        ...OBSERVER,
        requestCount: observerBefore.length + observerAfterCapable.length + observerAfter.length,
        closeRequestCount: 0
      },
      observerBefore,
      observerAfterCapable,
      observerAfter,
      postClosePing,
      calls,
      capableResponses,
      legacyResponses
    })
    await waitForFinish()
  } finally {
    await router.disconnectOnly().catch(() => {})
    router.dispose()
    await store?.freezeWritesAsync()
  }
}

void main().catch((error) => {
  process.send?.({
    type: 'error',
    message: error instanceof Error ? error.stack : String(error)
  })
  process.exit(1)
})

import { readFileSync } from 'node:fs'
import process from 'node:process'
import { randomUUID } from 'node:crypto'
import { DaemonPtyAdapter } from '../../../src/main/daemon/providers/adapter/daemon-pty-adapter'
import type { DaemonPtyRouter } from '../../../src/main/daemon/providers/routing/daemon-pty-router'
import { OrcaRuntimeService } from '../../../src/main/runtime/orca-runtime'
import { RpcDispatcher } from '../../../src/main/runtime/rpc/dispatcher'
import { SESSION_TAB_METHODS } from '../../../src/main/runtime/rpc/methods/session-tabs/session-tabs'
import type { RuntimeMobileSessionTabsSnapshot } from '../../../src/shared/remote-runtime/session-graph/runtime-session-contracts'
import { createDesktopDiscoveredDaemonRouter } from './daemon-generation-desktop-discovery'
import { dispatchFixtureCloseBursts } from './daemon-generation-runtime-close'
import { DAEMON_GENERATION_WORKTREE_ID } from './daemon-generation-fixture-contract'

type ClientGeneration = {
  protocolVersion: number
  socketPath: string
  tokenPath: string
}

type ClientSession = {
  protocolVersion: number
  sessionId: string
  rootPid: number
  label: string
  role: 'live' | 'stale-mirror'
}

type ClientConfig = {
  generations: ClientGeneration[]
  currentProtocolVersion: number
  daemonDir: string
  historyDir: string
  sessions: ClientSession[]
  reconnectBursts: number
  cwd: string
}

const WORKTREE_ID = DAEMON_GENERATION_WORKTREE_ID
const PARENT_TAB_ID = 'remote-reconnect-tab'
const MAX_OUTPUT_CHARS = 32_768

function readConfig(): ClientConfig {
  const configIndex = process.argv.indexOf('--config')
  const configPath = configIndex !== -1 ? process.argv[configIndex + 1] : undefined
  if (!configPath) {
    throw new Error('Reconnect client requires --config <path>')
  }
  return JSON.parse(readFileSync(configPath, 'utf8')) as ClientConfig
}

async function waitFor(description: string, predicate: () => boolean): Promise<void> {
  const deadline = Date.now() + 10_000
  while (Date.now() <= deadline) {
    if (predicate()) {
      return
    }
    await new Promise<void>((resolve) => setTimeout(resolve, 25))
  }
  throw new Error(`Timed out waiting for ${description}`)
}

function createDirectAdapters(
  generations: readonly ClientGeneration[]
): Map<number, DaemonPtyAdapter> {
  return new Map(
    generations.map((generation) => [
      generation.protocolVersion,
      new DaemonPtyAdapter({
        socketPath: generation.socketPath,
        tokenPath: generation.tokenPath,
        protocolVersion: generation.protocolVersion
      })
    ])
  )
}

async function connectThroughDesktopDiscovery(
  config: ClientConfig,
  burst: number
): Promise<DaemonPtyRouter> {
  const { router, adapters } = await createDesktopDiscoveredDaemonRouter(config)
  const outputBySessionId = new Map<string, string>()
  for (const adapter of adapters) {
    const protocolVersion = adapter.protocolVersion
    adapter.onData((event) => {
      const session = config.sessions.find(
        (candidate) =>
          candidate.protocolVersion === protocolVersion && candidate.sessionId === event.id
      )
      if (session) {
        outputBySessionId.set(
          event.id,
          `${outputBySessionId.get(event.id) ?? ''}${event.data}`.slice(-MAX_OUTPUT_CHARS)
        )
      }
    })
  }

  await router.getCurrentAdapter().listProcesses()
  await router.discoverLegacySessions()
  for (const session of config.sessions) {
    const attached = await router.spawn({
      sessionId: session.sessionId,
      isNewSession: false,
      cols: 100,
      rows: 30,
      cwd: config.cwd
    })
    if (!attached.isReattach || attached.pid !== session.rootPid) {
      throw new Error(`Reconnect changed ${session.label} process incarnation`)
    }
    const nonce = `reconnect-${burst}-${randomUUID().slice(0, 8)}`
    router.write(session.sessionId, `PING ${session.label} ${nonce}\r`)
    await waitFor(`${session.label} reconnect reply`, () =>
      (outputBySessionId.get(session.sessionId) ?? '').includes(
        `ORCA_GENERATION_CANARY_ACK ${session.label} ${nonce}`
      )
    )
  }
  return router
}

async function connectParallelRuntimeClients(config: ClientConfig): Promise<void> {
  const clients = [...createDirectAdapters(config.generations).values()]
  try {
    const lists = await Promise.all(clients.map((client) => client.listProcesses()))
    if (!lists.every((sessions) => sessions.length === 2)) {
      throw new Error('Parallel runtime client did not see both sessions in every generation')
    }
  } finally {
    await Promise.all(clients.map((client) => client.disconnectOnly()))
    clients.forEach((client) => client.dispose())
  }
}

function createRuntimeClosePath(
  config: ClientConfig,
  router: DaemonPtyRouter
): Promise<{
  dispatcher: RpcDispatcher
  targets: Map<string, { publicationEpoch: string; terminal: string }>
  pendingShutdowns: Promise<void>[]
}> {
  const pendingShutdowns: Promise<void>[] = []
  const surfaces = config.sessions.map((session, index) => {
    // Reuse mirror incarnation ids across relaunch so minting new tabs cannot weaken the repeated-close proof.
    const leafId = `00000000-0000-4000-8000-${String(index + 1).padStart(12, '0')}`
    return { session, leafId, mobileTabId: `${PARENT_TAB_ID}::${leafId}` }
  })
  const runtime = new OrcaRuntimeService()
  runtime.setPtyController({
    write: (ptyId, data) => {
      router.write(ptyId, data)
      return true
    },
    kill: (ptyId) => {
      const shutdown = router.shutdown(ptyId, { immediate: false })
      pendingShutdowns.push(shutdown)
      return true
    },
    listProcesses: (_hostId, options) => router.listProcesses(options),
    hasPty: (ptyId) => router.hasPty(ptyId),
    getForegroundProcess: (ptyId) => router.getForegroundProcess(ptyId)
  })
  runtime.setNotifier({
    closeTerminal: (tabId: string) => {
      throw new Error(`Reconnect fixture unexpectedly fell back to renderer tab close: ${tabId}`)
    }
  } as never)
  runtime.attachWindow(1)
  const snapshot: RuntimeMobileSessionTabsSnapshot = {
    worktree: WORKTREE_ID,
    publicationEpoch: 'stale-remote-mirror',
    snapshotVersion: 1,
    activeGroupId: null,
    activeTabId: surfaces[0]?.mobileTabId ?? null,
    activeTabType: surfaces.length > 0 ? 'terminal' : null,
    tabs: surfaces.map((surface, index) => ({
      type: 'terminal',
      id: surface.mobileTabId,
      parentTabId: PARENT_TAB_ID,
      leafId: surface.leafId,
      ptyId: surface.session.sessionId,
      title: surface.session.label,
      isActive: index === 0
    }))
  }
  runtime.syncWindowGraph(1, {
    tabs: [
      {
        tabId: PARENT_TAB_ID,
        worktreeId: WORKTREE_ID,
        title: 'Reconnect fixture',
        activeLeafId: surfaces[0]?.leafId ?? null,
        layout: null
      }
    ],
    leaves: surfaces.map((surface, index) => ({
      tabId: PARENT_TAB_ID,
      worktreeId: WORKTREE_ID,
      leafId: surface.leafId,
      paneRuntimeId: index + 1,
      ptyId: surface.session.sessionId,
      paneTitle: surface.session.label
    })),
    mobileSessionTabs: [snapshot]
  })
  return runtime.listMobileSessionTabs(`id:${WORKTREE_ID}`).then((accepted) => {
    const acceptedTerminalIds = accepted.tabs.flatMap((tab) =>
      tab.type === 'terminal' ? [tab.id] : []
    )
    if (!surfaces.every((surface) => acceptedTerminalIds.includes(surface.mobileTabId))) {
      throw new Error(`Runtime did not retain reconnect surfaces: ${JSON.stringify(accepted.tabs)}`)
    }
    const internals = runtime as unknown as {
      tabs: Map<string, unknown>
      mobileSessionTabsByWorktree: Map<string, RuntimeMobileSessionTabsSnapshot>
    }
    const stored = internals.mobileSessionTabsByWorktree.get(WORKTREE_ID)
    const storedLeafCount =
      stored?.tabs.filter((tab) => tab.type === 'terminal' && tab.parentTabId === PARENT_TAB_ID)
        .length ?? 0
    if (!internals.tabs.has(PARENT_TAB_ID) || storedLeafCount !== surfaces.length) {
      throw new Error(
        `Runtime close precondition drifted: parent=${internals.tabs.has(PARENT_TAB_ID)} leaves=${storedLeafCount}`
      )
    }
    return {
      dispatcher: new RpcDispatcher({ runtime, methods: SESSION_TAB_METHODS }),
      targets: new Map(
        surfaces
          .filter((surface) => surface.session.role === 'stale-mirror')
          .map((surface) => {
            const acceptedTab = accepted.tabs.find((tab) => tab.id === surface.mobileTabId)
            if (!acceptedTab || acceptedTab.type !== 'terminal' || acceptedTab.status !== 'ready') {
              throw new Error(`Missing lifecycle claim for ${surface.mobileTabId}`)
            }
            return [
              surface.mobileTabId,
              {
                publicationEpoch: accepted.publicationEpoch,
                terminal: acceptedTab.terminal
              }
            ] as const
          })
      ),
      pendingShutdowns
    }
  })
}

async function waitForFinish(): Promise<void> {
  await new Promise<void>((resolve) => {
    process.on('message', (message) => {
      if ((message as { type?: unknown })?.type === 'finish') {
        resolve()
      }
    })
  })
}

async function main(): Promise<void> {
  const config = readConfig()
  let router: DaemonPtyRouter | null = null
  try {
    for (let burst = 1; burst <= config.reconnectBursts; burst += 1) {
      if (router) {
        await router.disconnectOnly()
        router.dispose()
      }
      router = await connectThroughDesktopDiscovery(config, burst)
    }
    if (!router) {
      throw new Error('Reconnect fixture needs at least one reconnect burst')
    }
    await connectParallelRuntimeClients(config)
    const { dispatcher, targets, pendingShutdowns } = await createRuntimeClosePath(config, router)
    await dispatchFixtureCloseBursts({ dispatcher, worktreeId: WORKTREE_ID, targets })
    const shutdownResults = await Promise.allSettled(pendingShutdowns)
    const finish = waitForFinish()
    process.send?.({
      type: 'close-bursts-complete',
      closeAttempts: Object.fromEntries([...targets.keys()].map((tabId) => [tabId, 3])),
      shutdownResults: shutdownResults.map((result) => result.status)
    })
    await finish
  } finally {
    await router?.disconnectOnly().catch(() => {})
    router?.dispose()
  }
}

void main().catch((error) => {
  process.send?.({
    type: 'error',
    message: error instanceof Error ? error.stack : String(error)
  })
  process.exit(1)
})

