  let destroyed = false

  const debuggerObj = {
    isAttached: vi.fn(() => debuggerAttached),
    attach: vi.fn(() => {
      debuggerAttached = true
    }),
    detach: vi.fn(() => {
      debuggerAttached = false
    }),
    sendCommand: vi.fn(
      async (method?: string, _params?: Record<string, unknown>, _sessionId?: string) =>
        method === 'Page.captureScreenshot' ? { data: 'png' } : {}
    ),
    on: vi.fn((event: string, handler: DebuggerListener) => {
      const arr = listeners.get(event) ?? []
      arr.push(handler)
      listeners.set(event, arr)
    }),
    removeListener: vi.fn((event: string, handler: DebuggerListener) => {
      const arr = listeners.get(event) ?? []
      listeners.set(
        event,
        arr.filter((h) => h !== handler)
      )
    })
  }

  return {
    webContents: {
      debugger: debuggerObj,
      isDestroyed: () => destroyed,
      isCrashed: () => false,
      focus: vi.fn(),
      getType: vi.fn(() => 'window'),
      sendInputEvent: vi.fn(),
      setIgnoreMenuShortcuts: vi.fn(),
      printToPDF: vi.fn(async () => Buffer.from('%PDF-test')),
      reload: vi.fn(),
      reloadIgnoringCache: vi.fn(),
      getTitle: vi.fn(() => 'Example'),
      getURL: vi.fn(() => 'https://example.com')
    },
    listeners,
    destroy() {
      destroyed = true
    },
    emit(event: string, ...args: unknown[]) {
      for (const handler of listeners.get(event) ?? []) {
        handler(...args)
      }
    }
  }
}

export function mockAsWebContents(mock: MockWebContents, id?: number): WebContents {
  const contents = id === undefined ? mock.webContents : { ...mock.webContents, id }
  // oxlint-disable-next-line typescript/consistent-type-assertions -- SAFETY: the mock implements every WebContents member the CDP proxy and page-input paths call.
  return contents as unknown as WebContents
}

export type SendCommandCall = [string, Record<string, unknown>?, string?]

export function connect(endpoint: string): Promise<WebSocket> {
  return new Promise((resolve) => {
    const ws = new WebSocket(endpoint)
    ws.on('open', () => resolve(ws))
  })
}

export function nextMessage(ws: WebSocket): Promise<Record<string, unknown>> {
  return new Promise((resolve) => {
    ws.once('message', (data) => resolve(JSON.parse(data.toString())))
  })
}

export function sendAndReceive(
  ws: WebSocket,
  msg: Record<string, unknown>
): Promise<Record<string, unknown>> {
  const reply = nextMessage(ws)
  ws.send(JSON.stringify(msg))
  return reply
}

const PAINT_PROBE_EXPRESSION =
  "[performance.getEntriesByType('paint').length > 0, performance.timeOrigin]"

// Hides the first-paint probe every embedded-guest input passes; its own test spies on holdPaint.
export function getSendCommandCalls(mock: MockWebContents): SendCommandCall[] {
  // oxlint-disable-next-line typescript/consistent-type-assertions -- SAFETY: the mock records the (method, params, sessionId) it was called with.
  const calls = mock.webContents.debugger.sendCommand.mock.calls as unknown as SendCommandCall[]
  return calls.filter(
    ([method, params]) =>
      method !== 'Runtime.evaluate' || params?.expression !== PAINT_PROBE_EXPRESSION
  )
}

export function getSendCommandMethods(mock: MockWebContents): string[] {
  return getSendCommandCalls(mock).map((call) => call[0])
}

import type { OrchestrationDb } from '../../db/orchestration-db'
import { OrchestrationError } from '../../orchestration-error'
import type { MessageRow } from '../../db/orchestration-records'

export function openDecisionGateFromMessage(
  db: OrchestrationDb,
  msg: MessageRow,
  onLog: (msg: string) => void
): void {
  onLog(`Decision gate from ${msg.from_handle}: ${msg.subject}`)

  let payload: { taskId?: string; dispatchId?: string; question?: string; options?: string[] } = {}
  if (msg.payload) {
    try {
      payload = JSON.parse(msg.payload)
    } catch {
      return
    }
  }

  if (!payload.taskId || !payload.dispatchId || !payload.question) {
    onLog(`Warning: decision_gate missing taskId, dispatchId, or question`)
    return
  }

  try {
    db.createGate({
      taskId: payload.taskId,
      question: payload.question,
      options: payload.options,
      requester: {
        handle: msg.from_handle,
        paneKey: msg.sender_pane_key,
        dispatchId: payload.dispatchId
      }
    })
  } catch (error) {
    if (
      error instanceof OrchestrationError &&
      (error.code === 'consumer_fenced' || error.code === 'task_not_startable')
    ) {
      onLog(`Rejected decision gate from ${msg.from_handle}: ${error.message}`)
      return
    }
    throw error
  }

  onLog(`Task ${payload.taskId} blocked on decision gate`)
}

export function reblockTasksWithPendingGates(db: OrchestrationDb): void {
  // Only explicit human gate resolution may unblock these approval checkpoints.
  const pendingGates = db.listGates({ status: 'pending' })
  for (const gate of pendingGates) {
    const task = db.getTask(gate.task_id)
    if (task && task.status !== 'blocked') {
      db.updateTaskStatus(gate.task_id, 'blocked')
    }
  }
}

import type { DecisionGateRow, DispatchContextRow, GateStatus } from '../orchestration-records'
import { OrchestrationError } from '../../orchestration-error'
import { generateId } from '../generated-id'
import type { OrchestrationDb } from '../orchestration-db'
import { transitionLifecycleWithDb } from '../lifecycle-transition'
import { DISPATCH_CONTEXT_COLUMN_LIST } from '../row-column-lists'
import { remoteHoldOnTask } from '../remote-owned/remote-placements'

export function createGate(
  this: OrchestrationDb,
  gate: {
    taskId: string
    question: string
    options?: string[]
    requester?: { handle: string; paneKey?: string | null; dispatchId: string }
  }
): DecisionGateRow {
  this.db.exec('SAVEPOINT create_gate')
  try {
    const task = this.getTask(gate.taskId)
    if (!task) {
      throw new OrchestrationError(
        'lifecycle_not_found',
        `Task ${gate.taskId} was not found while creating a decision gate.`,
        { taskId: gate.taskId }
      )
    }
    const runId = task.run_id
    this.requireRun(runId)
    const rawActive = this.db
      .prepare(
        `SELECT ${DISPATCH_CONTEXT_COLUMN_LIST} FROM dispatch_contexts
         WHERE task_id = ? AND status IN ('pending', 'dispatched')
         ORDER BY rowid DESC LIMIT 1`
      )
      .get(gate.taskId)
    // oxlint-disable-next-line typescript/consistent-type-assertions -- SAFETY: The schema-pinned complete Dispatch projection returns one Dispatch row or undefined; the adapter exposes unknown.
    const active = rawActive as DispatchContextRow | undefined
    if (
      gate.requester &&
      (!active ||
        active.id !== gate.requester.dispatchId ||
        !this.isDispatchMessageSender({
          dispatchId: active.id,
          handle: gate.requester.handle,
          paneKey: gate.requester.paneKey,
          allowCanonicalDispatchHandle: true
        }))
    ) {
      throw new OrchestrationError(
        'consumer_fenced',
        `Terminal ${gate.requester.handle} does not own the active Dispatch for Task ${gate.taskId}.`,
        { taskId: gate.taskId, dispatchId: active?.id }
      )
    }
    const localWorker = this.db
      .prepare(
        `SELECT active.id
         FROM dispatch_contexts active
         JOIN worker_dispatches worker ON worker.dispatch_id = active.id
         WHERE active.task_id = ? AND active.status IN ('pending', 'dispatched')
           AND worker.state NOT IN ('failed', 'succeeded', 'stopped', 'abandoned')
         ORDER BY active.rowid DESC LIMIT 1`
      )
      .get(gate.taskId) as { id: string } | undefined
    // A worker a paired server runs for the Task holds it exactly as a local one does.
    const remote = remoteHoldOnTask(this, gate.taskId)
    const activeWorker =
      localWorker ??
      (remote?.liveWorker ? { id: remote.dispatchId ?? '(a start on a paired server)' } : undefined)
    if (activeWorker) {
      throw new OrchestrationError(
        'task_not_startable',
        `Task ${gate.taskId} cannot open a gate while supervised Dispatch ${activeWorker.id} is active; stop or settle its worker first.`,
        { taskId: gate.taskId, dispatchId: activeWorker.id }
      )
    }
    const id = generateId('gate')
    const optionsJson = JSON.stringify(gate.options ?? [])
    this.db
      .prepare(
        'INSERT INTO decision_gates (id, run_id, task_id, question, options) VALUES (?, ?, ?, ?, ?)'
      )
      .run(id, runId, gate.taskId, gate.question, optionsJson)
    this.completeActiveDispatchesForTask(gate.taskId)
    transitionLifecycleWithDb(this.db, {
      entity: 'task',
      id: gate.taskId,
      from: task.status,
      to: 'blocked'
    })
    const created = this.db.prepare('SELECT * FROM decision_gates WHERE id = ?').get(id) as
      | DecisionGateRow
      | undefined
    this.db.exec('RELEASE create_gate')
    return created as DecisionGateRow
  } catch (error) {
    this.db.exec('ROLLBACK TO create_gate')
    this.db.exec('RELEASE create_gate')
    throw error
  }
}

export function resolveGate(
  this: OrchestrationDb,
  gateId: string,
  resolution: string
): DecisionGateRow | undefined {
  const gate = this.db.prepare('SELECT * FROM decision_gates WHERE id = ?').get(gateId) as
    | DecisionGateRow
    | undefined
  if (!gate) {
    return undefined
  }

  this.db.exec('SAVEPOINT resolve_gate')
  try {
    this.db
      .prepare(
        "UPDATE decision_gates SET status = 'resolved', resolution = ?, resolved_at = datetime('now') WHERE id = ?"
      )
      .run(resolution, gateId)
    this.updateTaskStatus(gate.task_id, 'ready')
    const resolved = this.db.prepare('SELECT * FROM decision_gates WHERE id = ?').get(gateId) as
      | DecisionGateRow
      | undefined
    this.db.exec('RELEASE resolve_gate')
    return resolved
  } catch (error) {
    this.db.exec('ROLLBACK TO resolve_gate')
    this.db.exec('RELEASE resolve_gate')
    throw error
  }
}

export function timeoutGate(this: OrchestrationDb, gateId: string): DecisionGateRow | undefined {
  this.db
    .prepare(
      // A late timeout must not overwrite an already resolved gate.
      "UPDATE decision_gates SET status = 'timeout', resolved_at = datetime('now') WHERE id = ? AND status = 'pending'"
    )
    .run(gateId)
  return this.db.prepare('SELECT * FROM decision_gates WHERE id = ?').get(gateId) as
    | DecisionGateRow
    | undefined
}

export function listGates(
  this: OrchestrationDb,
  filter?: { taskId?: string; status?: GateStatus }
): DecisionGateRow[] {
  if (filter?.taskId && filter?.status) {
    return this.db
      .prepare('SELECT * FROM decision_gates WHERE task_id = ? AND status = ? ORDER BY created_at')
      .all(filter.taskId, filter.status) as DecisionGateRow[]
  }
  if (filter?.taskId) {
    return this.db
      .prepare('SELECT * FROM decision_gates WHERE task_id = ? ORDER BY created_at')
      .all(filter.taskId) as DecisionGateRow[]
  }
  if (filter?.status) {
    return this.db
      .prepare('SELECT * FROM decision_gates WHERE status = ? ORDER BY created_at')
      .all(filter.status) as DecisionGateRow[]
  }
  return this.db
    .prepare('SELECT * FROM decision_gates ORDER BY created_at')
    .all() as DecisionGateRow[]
}

export function getGate(this: OrchestrationDb, id: string): DecisionGateRow | undefined {
  return this.db.prepare('SELECT * FROM decision_gates WHERE id = ?').get(id) as
    | DecisionGateRow
    | undefined
}

export type DecisionGateStoreMethods = {
  createGate: typeof createGate
  resolveGate: typeof resolveGate
  timeoutGate: typeof timeoutGate
  listGates: typeof listGates
  getGate: typeof getGate
}

export function attachDecisionGateStore(ctor: { prototype: object }): void {
  Object.assign(ctor.prototype, {
    createGate,
    resolveGate,
    timeoutGate,
    listGates,
    getGate
  })
}

export function resampleToRate(
  samples: Float32Array,
  inputSampleRate: number,
  outputSampleRate: number
): Float32Array {
  if (
    samples.length === 0 ||
    !Number.isFinite(inputSampleRate) ||
    !Number.isFinite(outputSampleRate) ||
    inputSampleRate <= 0 ||
    outputSampleRate <= 0 ||
    inputSampleRate === outputSampleRate
  ) {
    return samples
  }

  const outputLength = Math.max(
    1,
    Math.round((samples.length * outputSampleRate) / inputSampleRate)
  )
  const output = new Float32Array(outputLength)
  const ratio = inputSampleRate / outputSampleRate
  for (let i = 0; i < outputLength; i += 1) {
    const sourceIndex = i * ratio
    const left = Math.floor(sourceIndex)
    const right = Math.min(left + 1, samples.length - 1)
    const weight = sourceIndex - left
    output[i] = samples[left] * (1 - weight) + samples[right] * weight
  }
  return output
}

